const MovieCard = ({ movie }) => {
  if (!movie || !movie.posterUrl || !movie.title) {
    return null; // Ensure only valid movies render
  }

  return (
    <div className="movie-card cursor-pointer">
      <img
        className="w-full h-64 object-cover"
        src={movie.posterUrl}
        alt={movie.title}
      />
      <div className="p-4">
        <h3 className="text-lg font-semibold">{movie.title}</h3>
        {/* Remove the paragraph below or conditionally render if genre is meaningful */}
        {/* <p className="text-sm text-gray-500">{movie.genre}</p> */}
      </div>
    </div>
  );
};

export default MovieCard;
